          "html": "<section class=\"revealPart\" id=\"focus-paragraph-1-0\">\n<h3>完整原文 · 第1段</h3>\n<p>Every Saturday morning, at 9 am, more than 50,000 runners set off to run 5km around their local park. The Parkrun phenomenon began with a dozen friends and has inspired 400 events in the UK and more abroad. Events are free, staffed by thousands of volunteers. Runners range from four years old to grandparents; their times range from Andrew Baddeley’s world record 13 minutes 48 seconds up to an hour.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-1-1\">\n<h3>意群划分 · 第1段</h3>\n<p>Every Saturday morning, / at 9 am, / more than 50,000 runners set off to run 5km around their local park. / The Parkrun phenomenon began with a dozen friends and has inspired 400 events in the UK and more abroad. / Events are free, / staffed by thousands of volunteers. / Runners range from four years old to grandparents; / their times range from Andrew Baddeley’s world record 13 minutes 48 seconds up to an hour.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-1-2\">\n<h3>意群翻译 · 第1段</h3>\n<p style=\"line-height:1.8;color:#2563eb;font-weight:500\">每周六早上 / 上午 9 点 / 超过 50,000 名跑步者出发，围绕当地公园跑 5 公里<br>Parkrun 现象始于十几个朋友，并启发了英国和更多海外地区的 400 场活动<br>活动免费 / 由数千名志愿者组成<br>跑步者的年龄范围从四岁到祖父母 / 他们的时间范围从安德鲁·巴德利 (Andrew Baddeley) 的世界纪录 13 分 48 秒到 1 小时不等</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-1-3\">\n<h3>标准译文 · 第1段</h3>\n<p>每周六早上 9 点，超过 50,000 名跑步者出发，围绕当地公园跑 5 公里。 Parkrun 现象始于十几个朋友，并启发了英国和其他国家举办的 400 场活动。活动是免费的，有数千名志愿者。跑步者的年龄范围从四岁到祖父母；他们的时间从安德鲁·巴德利 (Andrew Baddeley) 的世界纪录 13 分 48 秒到 1 小时不等。</p>\n</section>",
