          "html": "<section class=\"revealPart\" id=\"focus-paragraph-2-0\">\n<h3>完整原文 · 第2段</h3>\n<p>Parkrun is succeeding where London’s Olympic “legacy” is failing. Ten years ago on Monday, it was announced that the Games of the 30th Olympiad would be in London. Planning documents pledged that the great legacy of the Games would be to lever a nation of sport lovers away from their couches. The population would be fitter, healthier and produce more winners. It has not happened. The number of adults doing weekly sport did rise, by nearly 2 million in the run-up to 2012—but the general population was growing faster. Worse, the numbers are now falling at an accelerating rate. The opposition claims primary school pupils doing at least two hours of sport a week have nearly halved. Obesity has risen among adults and children. Official retrospections continue as to why London 2012 failed to “inspire a generation.” The success of Parkrun offers answers.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-2-1\">\n<h3>意群划分 · 第2段</h3>\n<p>Parkrun is succeeding / where London’s Olympic “legacy” is failing. / Ten years ago on Monday, / it was announced / that the Games of the 30th Olympiad would be in London. / Planning documents pledged / that the great legacy of the Games would be to lever a nation of sport lovers away from their couches. / The population would be fitter, / healthier and produce more winners. / It has not happened. / The number of adults doing weekly sport did rise, / by nearly 2 million in the run-up to 2012—but the general population was growing faster. / Worse, / the numbers are now falling at an accelerating rate. / The opposition claims primary school pupils doing at least two hours of sport a week have nearly halved. / Obesity has risen among adults and children. / Official retrospections continue as to why London 2012 failed to “inspire a generation.” The success of Parkrun offers answers.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-2-2\">\n<h3>意群翻译 · 第2段</h3>\n<p style=\"line-height:1.8;color:#2563eb;font-weight:500\">帕克润正在取得成功 / 伦敦奥运“遗产”正在失败的地方<br>十年前的星期一 / 已宣布 / 第30届奥运会将在伦敦举行<br>规划文件承诺 / 奥运会的伟大遗产将是让全国的体育爱好者远离沙发<br>人口会更加健康 / 更健康并产生更多赢家<br>这还没有发生<br>每周进行体育运动的成年人数量确实有所增加 / 到 2012 年，人口增长了近 200 万，但总体人口增长速度更快<br>更糟糕的是 / 这个数字现在正在加速下降<br>反对派声称，小学生每周至少进行两小时体育运动的人数几乎减少了一半<br>成人和儿童的肥胖率有所上升<br>官方仍在继续反思为什么 2012 年伦敦奥运会未能“激励一代人”。 Parkrun的成功给出了答案</p>\n</section>",
