          "html": "<section class=\"revealPart\" id=\"focus-paragraph-4-0\">\n<h3>完整原文 · 第4段</h3>\n<p>Indeed, there is something a little absurd in the state getting involved in the planning of such a fundamentally “grassroots” concept as community sports associations. If there is a role for government, it should really be getting involved in providing common goods— making sure there is space for playing fields and the money to pave tennis and netball courts, and encouraging the provision of all these activities in schools. But successive governments have presided over selling green spaces, squeezing money from local authorities and declining attention on sport in education. Instead of wordy, worthy strategies, future governments need to do more to provide the conditions for sport to thrive. Or at least not make them worse.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-4-1\">\n<h3>意群划分 · 第4段</h3>\n<p>Indeed, / there is something a little absurd in the state getting involved in the planning of such a fundamentally “grassroots” concept as community sports associations. / If there is a role for government, / it should really be getting involved in providing common goods— / making sure there is space for playing fields and the money to pave tennis and netball courts, / and encouraging the provision of all these activities in schools. / But successive governments have presided over selling green spaces, / squeezing money from local authorities and declining attention on sport in education. / Instead of wordy, / worthy strategies, / future governments need to do more to provide the conditions for sport to thrive. / Or at least not make them worse.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-4-2\">\n<h3>意群翻译 · 第4段</h3>\n<p style=\"line-height:1.8;color:#2563eb;font-weight:500\">的确 / 国家参与社区体育协会这样一个“草根”概念的规划，有点荒唐<br>如果政府可以发挥作用 / 它确实应该参与提供共同物品 / 确保有运动场的空间和铺设网球场和无挡板篮球场的资金 / 并鼓励在学校开展所有这些活动<br>但历届政府都主持出售绿地 / 挤压地方当局的资金以及教育中对体育的关注度下降<br>而不是啰嗦 / 有价值的策略 / 未来政府需要采取更多措施为体育蓬勃发展提供条件<br>或者至少不会让事情变得更糟</p>\n</section>",
