          "html": "<div class=\"coarseStack\"><div class=\"coarsePara currentFocus\"><p>With so much focus on children’s use of screens, / it’s easy for parents to forget about their own screen use. “Tech is designed to really suck you in,” says Jenny Radesky in her study of digital play, / “and digital products are there to promote maximal engagement. / It makes it hard to disengage, / and leads to a lot of bleed-over into the family routine. ”</p></div></div>",
