          "raw": "### C. simplify routine matters\n\n> 简化日常事务\n\n我们先看 C 选项：`simplify routine matters`（简化日常事务）。\n\n我们把 C 选项的内容代入题干进行语义检验：\n\n> **题干结合选项**：根据 Jenny Radesky 的说法，数字产品的设计目的是“简化日常事务”。\n\n**定位原文与比对分析：**\n\n1. **【考研命题典型陷阱：无中生有 / 过度推断】**：\n   - 在原文第 1 段的表述中，作者仅陈述了相关背景事实，根本没有提及选项所主张的“简化日常事务”这种极端结论。考生容易凭主观常识进行过度脑补，但该推论在原文中缺乏直接文本依据（孤证不立）。\n\n2. **原文与选项的本质差异**：\n   - 原文强调的是上下文逻辑严密的客观事实，而选项在表述上存在明显的偏差或逻辑断层，无法与题干构成直接合理的答题闭环。\n\n**第一轮判断：C直接排除。**",
