          "title": "第2段 · 篇章精读",
          "html": "<section class=\"revealPart\" id=\"focus-paragraph-2-0\">\n<h3>完整原文 · 第2段</h3>\n<p>Radesky has studied the use of mobile phones and tablets at mealtimes by giving mother- child pairs a food-testing exercise. She found that mothers who used devices during the exercise started 20 per cent fewer verbal and 39 per cent fewer nonverbal interactions with their children. During a separate observation, she saw that phones became a source of tension in the family. Parents would be looking at their emails while the children would be making excited bids for their attention.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-2-1\">\n<h3>意群划分 · 第2段</h3>\n<p>Radesky has studied the use of mobile phones and tablets at mealtimes by giving mother- child pairs a food-testing exercise. / She found / that mothers / who used devices during the exercise started 20 per cent fewer verbal and 39 per cent fewer nonverbal interactions with their children. / During a separate observation, / she saw / that phones became a source of tension in the family. / Parents would be looking at their emails / while the children would be making excited bids for their attention.</p>\n</section>",
