          "html": "<section class=\"revealPart\">\n<h4>句子精析 (1/4)</h4>\n<p style=\"font-family:'Times New Roman',serif;font-size:1.15em;color:#1e293b;line-height:1.7\"><strong>原句：</strong>Infants are wired to look at parents’ faces to try to understand their world, and if those faces are blank and unresponsive—as they often are when absorbed in a device—it can be extremely disconcerting for the children.</p>\n<p><strong>意群断句：</strong><code>Infants are wired to look at parents’ faces to try to understand their world, / and / if those faces are blank and unresponsive—as they often are / when absorbed in a device—it can be extremely disconcerting for the children.</code></p>\n<p style=\"margin:8px 0\"><strong>【意群翻译】：</strong><span style=\"color:#2563eb;font-weight:500;font-size:1.02em\">婴儿天生会通过观察父母的脸来尝试了解他们的世界 / 和 / 如果那些人脸上表情茫然、毫无反应——就像他们经常做的那样 / 当孩子全神贯注于某个设备时，可能会感到非常不安</span></p>\n<div style=\"margin:8px 0;background:#f8fafc;border-left:4px solid #0f766e;padding:8px 12px;border-radius:0 6px 6px 0\">\n  <p style=\"font-weight:bold;color:#0f766e;margin-bottom:4px\">【句法拆解与逻辑剖析】</p>\n  <ul style=\"margin:6px 0 0 18px;padding:0;line-height:1.7;color:#334155\"><li style=\"margin-bottom:5px\"><b>主干结构剖析</b>：全句为主谓宾/主系表基础陈述结构，核心主干明确，意群衔接紧密自然。</li></ul>\n</div>\n<p style=\"margin-top:8px\"><strong>【满分参考汉译】</strong><span style=\"color:#0f766e;font-weight:600;font-size:1.05em\">婴儿天生会看着父母的脸来试图了解他们的世界，如果父母的脸一片空白且毫无反应——就像他们全神贯注于某个设备时经常出现的情况一样——这可能会让孩子们感到非常不安。</span></p>\n</section>",
