          "html": "<section class=\"revealPart\">\n<h4>句子精析 (3/4)</h4>\n<p style=\"font-family:'Times New Roman',serif;font-size:1.15em;color:#1e293b;line-height:1.7\"><strong>原句：</strong>In it, a mother is asked to interact with her child in a normal way before putting on a blank expression and not giving them any visual social feedback: The child becomes increasingly distressed as she tries to capture her mother’s attention.</p>\n<p><strong>意群断句：</strong><code>In it, / a mother is asked to interact with her child in a normal way / before putting on a blank expression and not giving them any visual social feedback: / The child becomes increasingly distressed as she tries to capture her mother’s attention.</code></p>\n<p style=\"margin:8px 0\"><strong>【意群翻译】：</strong><span style=\"color:#2563eb;font-weight:500;font-size:1.02em\">在其中 / 要求母亲以正常方式与孩子互动 / 在表现出茫然的表情并且不给他们任何视觉社交反馈之前 / 当孩子试图引起母亲的注意时，她变得越来越痛苦</span></p>\n<div style=\"margin:8px 0;background:#f8fafc;border-left:4px solid #0f766e;padding:8px 12px;border-radius:0 6px 6px 0\">\n  <p style=\"font-weight:bold;color:#0f766e;margin-bottom:4px\">【句法拆解与逻辑剖析】</p>\n  <ul style=\"margin:6px 0 0 18px;padding:0;line-height:1.7;color:#334155\"><li style=\"margin-bottom:5px\"><b>介词短语修饰</b>：<code>with her child in a normal way before pu...</code> 充当状语或定语，补充方式、伴随或背景条件。</li></ul>\n</div>\n<p style=\"margin-top:8px\"><strong>【满分参考汉译】</strong><span style=\"color:#0f766e;font-weight:600;font-size:1.05em\">其中，母亲被要求以正常方式与孩子互动，然后表现出茫然的表情，不给他们任何视觉社交反馈：当孩子试图吸引母亲的注意力时，她变得越来越痛苦。</span></p>\n</section>",
