          "html": "<section class=\"revealPart\" id=\"focus-paragraph-4-0\">\n<h3>完整原文 · 第4段</h3>\n<p>On the other hand, Tronick himself is concerned that the worries about kids’ use of screens are born out of an “oppressive ideology that demands that parents should always be interacting” with their children: “It’s based on a somewhat fantasised, very white, very upper- middle-class ideology that says if you’re failing to expose your child to 30,000 words you are neglecting them.” Tronick believes that just because a child isn’t learning from the screen doesn’t mean there’s no value to it—particularly if it gives parents time to have a shower, do housework or simply have a break from their child. Parents, he says, can get a lot out of using their devices to speak to a friend or get some work out of the way. This can make them feel happier, which lets them be more available to their child the rest of the time.</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-4-1\">\n<h3>意群划分 · 第4段</h3>\n<p>On the other hand, / Tronick himself is concerned / that the worries about kids’ use of screens are born out of an “oppressive ideology / that demands / that parents should always be interacting” with their children: / “It’s based on a somewhat fantasised, / very white, / very upper- middle-class ideology / that says / if you’re failing to expose your child to 30,000 words you are neglecting them.” Tronick believes / that just / because a child isn’t learning from the screen doesn’t mean there’s no value to it—particularly / if it gives parents time to have a shower, / do housework or simply have a break from their child. / Parents, / he says, / can get a lot out of using their devices to speak to a friend or get some work out of the way. / This can make them feel happier, / / which lets them be more available to their child the rest of the time.</p>\n</section>",
