          "section": "先读题干",
          "raw": "## 36题题干\n\n**More frequent wildfires have become a national concern because in 2015 they _______.**\n\n> 更频繁的野火已成为全国关注的问题，因为 2015 年它们_______。\n\n题型：**事实细节题**。\n\n定位预判：**Paragraph 1**\n\n---",
          "html": "<h2>36题题干</h2><p><strong>More frequent wildfires have become a national concern because in 2015 they _______.</strong></p><blockquote><p>更频繁的野火已成为全国关注的问题，因为 2015 年它们_______。</p></blockquote><p>题型：<strong>事实细节题</strong>。</p><p>定位预判：<strong>Paragraph 1</strong></p><hr />",
