          "html": "<section class=\"revealPart\">\n<h4>句子精析 (1/1)</h4>\n<p style=\"font-family:'Times New Roman',serif;font-size:1.15em;color:#1e293b;line-height:1.7\"><strong>原句：</strong>Though often viewed as a problem for western states, the growing frequency of wildfires is a national concern because of its impact on federal tax dollars, says Professor Max Moritz, a specialist in fire ecology and management.</p>\n<p><strong>意群断句：</strong><code>Though often viewed as a problem for western states, / the growing frequency of wildfires is a national concern / because of its impact on federal tax dollars, / says Professor Max Moritz, / a specialist in fire ecology and management.</code></p>\n<p style=\"margin:8px 0\"><strong>【意群翻译】：</strong><span style=\"color:#2563eb;font-weight:500;font-size:1.02em\">尽管经常被视为西方国家的问题 / 野火日益频繁是全国关注的问题 / 因为它对联邦税收的影响 / 马克斯·莫里茨教授说 / 火灾生态学和管理专家</span></p>\n<div style=\"margin:8px 0;background:#f8fafc;border-left:4px solid #0f766e;padding:8px 12px;border-radius:0 6px 6px 0\">\n  <p style=\"font-weight:bold;color:#0f766e;margin-bottom:4px\">【句法拆解与逻辑剖析】</p>\n  <ul style=\"margin:6px 0 0 18px;padding:0;line-height:1.7;color:#334155\"><li style=\"margin-bottom:5px\"><b>时间/伴随状语从句</b>：句首 <code>As a problem for western states</code> 引导时间/伴随状语从句（“正当……之时 / 随着……”），交代主句动作发生的背景与伴随情境。</li><li style=\"margin-bottom:5px\"><b>让步状语从句</b>：由连词 <code>Though</code> 引导从句 <code>Though often viewed as a problem for western states</code>，限定主句论述的时空背景或逻辑前提。</li></ul>\n</div>\n<p style=\"margin-top:8px\"><strong>【满分参考汉译】</strong><span style=\"color:#0f766e;font-weight:600;font-size:1.05em\">火灾生态和管理专家马克斯·莫里茨教授表示，尽管野火经常被视为西部各州的一个问题，但由于其对联邦税收的影响，野火的日益频繁也成为全国关注的问题。</span></p>\n</section>",
