          "html": "<section class=\"revealPart\" id=\"focus-paragraph-8-0\">\n<h3>完整原文 · 第8段</h3>\n<p>“The human systems and the landscapes we live on are linked, and the interactions go both ways,” he says. Failing to recognize that, he notes, leads to “an overly simplified view of what the solutions might be. Our perception of the problem and of what the solution is becomes very limited.”</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-8-1\">\n<h3>意群划分 · 第8段</h3>\n<p>“The human systems and the landscapes we live on are linked, / and the interactions go both ways,” he says. / Failing to recognize that, / he notes, / leads to “an overly simplified view of what the solutions might be. / Our perception of the problem and of what the solution is becomes very limited.”</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-8-2\">\n<h3>意群翻译 · 第8段</h3>\n<p style=\"line-height:1.8;color:#2563eb;font-weight:500\">The human systems and the landscapes we live on are linked / 而且互动是双向的，”他说<br>未能认识到这一点 / 他指出 / 导致“对解决方案的看法过于简单<br>我们对问题和解决方案的看法变得非常有限。”</p>\n</section>\n<section class=\"revealPart\" id=\"focus-paragraph-8-3\">\n<h3>标准译文 · 第8段</h3>\n<p>“人类系统和我们赖以生存的景观是相互联系的，而且相互作用是双向的，”他说。他指出，如果没有认识到这一点，就会导致“对解决方案的看法过于简单化。我们对问题和解决方案的看法变得非常有限。”</p>\n</section>",
